-- ============================================================
-- CANADA — phase 2c : toutes les municipalités habitées (ca_cities)
-- Source : Statistique Canada, tableau 98-10-0002-01, Recensement 2021,
-- subdivisions de recensement (DGUID 2021A0005…). Fichier téléchargé le 26/10/2026.
-- 4 722 municipalités avec population > 0. En cas d'homonymes dans une même
-- province (108 cas, surtout paroisse/municipalité au Québec), seule la plus
-- peuplée est gardée. Noms bilingues « Greater Sudbury / Grand Sudbury » :
-- anglais dans city, français dans city_fr. timezone laissé vide (non sourcé).
-- Les 41 villes déjà en base ne sont pas modifiées (sauf dguid et city_fr vides).
-- Idempotent.
-- ============================================================

ALTER TABLE ca_cities ADD COLUMN IF NOT EXISTS dguid text;

-- Slugs : tirets, jamais d'espace (même format que les URL /ca/…)
UPDATE ca_cities c
SET city_ascii = replace(lower(btrim(c.city_ascii)), ' ', '-')
WHERE c.city_ascii ~ '\s|[A-Z]'
  AND NOT EXISTS (
    SELECT 1 FROM ca_cities d
    WHERE d.province_id = c.province_id
      AND d.city_ascii = replace(lower(btrim(c.city_ascii)), ' ', '-')
  );

