ON CONFLICT (province_id, city_ascii) DO UPDATE SET
  dguid   = COALESCE(ca_cities.dguid, EXCLUDED.dguid),
  city_fr = COALESCE(ca_cities.city_fr, EXCLUDED.city_fr);

-- Contrôle : villes par province + vérification de quelques grandes villes
SELECT province_id, count(*) AS villes, max(population) AS plus_grande
FROM ca_cities GROUP BY province_id
UNION ALL
SELECT 'TOTAL', count(*), NULL FROM ca_cities
ORDER BY 1;
